using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using OneWay.Battle3D;
public static class TestPlayableNewAttacks
{
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 public static object Run(){
  Check(Application.isPlaying,"Requires Play Mode");var combo=UnityEngine.Object.FindFirstObjectByType<NewPlayerAttackCombo>();var p=combo.GetComponent<BattlePlayerController>();var body=p.GetComponent<BattleArenaBody>();var motor=p.GetComponent<CharacterController>();var oldBoss=p.boss;var oldFeedback=p.feedback;var oldPos=p.transform.position;var oldRot=p.transform.rotation;bool pe=p.enabled,be=body.enabled;var ground=GameObject.CreatePrimitive(PrimitiveType.Cube);ground.name="Temporary attack test ground";ground.transform.position=new Vector3(1000,-.5f,1000);ground.transform.localScale=new Vector3(100,1,100);var dummy=new GameObject("Temporary strike target");var collider=dummy.AddComponent<SphereCollider>();collider.radius=.5f;collider.isTrigger=true;var boss=dummy.AddComponent<BattleBoss>();boss.maxHealth=100000;boss.ResetBoss();boss.hitbox=collider;p.enabled=false;body.enabled=false;p.boss=boss;p.feedback=null;combo.readMouseInput=false;var logs=new List<string>();Application.LogCallback handler=(m,s,t)=>{if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)logs.Add(m);};Application.logMessageReceived+=handler;
  Action reset=()=>{combo.Cancel();motor.enabled=false;p.transform.position=new Vector3(1000,.01f,1000);motor.enabled=true;Physics.SyncTransforms();combo.RequestAttack();};
  Action tick=()=>{boss.transform.position=p.transform.position+p.transform.forward*2;Physics.SyncTransforms();combo.Tick(.5f/30f);};
  Action<int> reach=target=>{reset();for(int n=0;n<5000;n++){if(!combo.InPreparation&&combo.SequenceIndex==target&&combo.Frame<.01f)return;if(!combo.InPreparation)combo.RequestAttack();tick();}throw new Exception("Could not reach step "+target);};
  try{
   reset();int initial=combo.DamageApplications;var visited=new HashSet<int>();float maxJump=0;bool finished=false;
   for(int n=0;n<5000;n++){if(!combo.InPreparation){visited.Add(combo.SequenceIndex);combo.RequestAttack();}tick();if(combo.AttackIndex==5)maxJump=Mathf.Max(maxJump,p.transform.position.y);if(visited.Count==7&&combo.SequenceIndex==0&&combo.InPreparation){finished=true;break;}}
   int strikes=combo.DamageApplications-initial;Check(finished&&visited.Count==7,"Seven step chain incomplete");Check(strikes==8,"Expected 8 independent hits, got "+strikes);Check(maxJump>.4f,"Jump was not raised");
   var recovery=new List<object>();for(int i=0;i<7;i++){reach(i);int hits=combo.DamageApplications;int index=combo.AttackIndex;float end=combo.motions.attacks[index].Frames;int guard=0;while(combo.IsActive&&guard++<2000)tick();Check(!combo.IsActive,"Recovery stuck "+i);Check(Mathf.Abs(combo.Frame-end)<.01f,"Incorrect full recovery end");Check(p.animator.GetCurrentAnimatorStateInfo(0).IsName("Idle"),"Idle did not resume");int count=combo.DamageApplications-hits;Check(count==(index==2?2:1),"Recovery damage count "+i+"="+count);recovery.Add(new{step=i+1,attack=index+1,endFrame=end,hits=count});}
   reach(6);var start=p.transform.position;while(combo.Frame<13)tick();var at13=p.transform.position;while(combo.Frame<27)tick();var at27=p.transform.position;while(combo.Frame<30)tick();var at30=p.transform.position;float retreat=Vector3.Dot(start-at13,p.transform.forward),hold=Vector3.ProjectOnPlane(at27-at13,Vector3.up).magnitude,returned=Vector3.ProjectOnPlane(at30-start,Vector3.up).magnitude;Check(Mathf.Abs(retreat-combo.attackRetreatDistance)<.02f,"Retreat mismatch "+retreat);Check(hold<.005f,"Retreat hold moved");Check(returned<.02f,"Return displacement "+returned);
   while(combo.Frame<86)tick();Check(!combo.InPreparation&&combo.IsActive,"Unqueued attack ended at 86");tick();combo.RequestAttack();Check(!combo.Queued,"Late input incorrectly queued during recovery");
   reach(6);combo.RequestAttack();while(!combo.InPreparation)tick();Check(combo.SequenceIndex==0&&combo.Frame<.01f,"Attack01 queued branch failed");
   reach(0);start=p.transform.position;while(combo.Frame<10)tick();float dash=Vector3.Dot(p.transform.position-start,p.transform.forward);Check(Mathf.Abs(dash-combo.skillDashDistance)<.02f,"Skill dash distance "+dash);
   reach(3);float baseHeight=p.transform.position.y;int jumpArcs=0;bool airborne=false;while(combo.IsActive){tick();bool nextAir=p.transform.position.y>baseHeight+.02f;if(nextAir&&!airborne)jumpArcs++;airborne=nextAir;if(combo.Frame<=9.5f)Check(!nextAir,"Unwanted early jump");}Check(jumpArcs==1,"Expected one jump, got "+jumpArcs);reach(3);while(combo.Frame<8)tick();combo.Cancel();Check(!combo.IsActive&&!combo.Queued,"Cancel did not clear combo");Check(Mathf.Abs(p.transform.position.y-.01f)<.1f,"Jump cancel left character airborne");Check(logs.Count==0,"Unity errors: "+string.Join("|",logs));
   var result=new{passed=true,sevenStepStrikes=strikes,recovery,retreat,stationaryDrift=hold,returnError=returned,skillDash=dash,peakJump=maxJump,errors=logs};System.IO.File.WriteAllText("Assets/3DBattle/Authoring~/PlayableNewAttackTests.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;
  }finally{Application.logMessageReceived-=handler;combo.Cancel();p.boss=oldBoss;p.feedback=oldFeedback;motor.enabled=false;p.transform.SetPositionAndRotation(oldPos,oldRot);motor.enabled=true;body.enabled=be;p.enabled=pe;combo.readMouseInput=true;UnityEngine.Object.DestroyImmediate(dummy);UnityEngine.Object.DestroyImmediate(ground);}
 }
}

